// moonproof v3 shell: one hash router for every route of the static site.
// Views are lazy-loaded ES modules in ./views/. The board (onboard cockpit) and the 3D terrain lab
// keep their own pages (their CSP and scripts differ) and are reached through the same routes.
// Source of truth: this .tsx file (Preact). app.js is generated by `npm --prefix web run build:ts`.
import { h, Fragment, render } from "../vendor/preact/preact.module.js";
import { startRouter, buildHash, bordoURL, loadLastRoute, parseHash } from "../ds/router.js";
import { ProvStrip, mount } from "../ds/ui.js";
import { MODES, TOOLS, activeMode, scenarioQuery } from "./modes.js";
import { initMoonStage } from "./moon-stage.js";
const ICONS = {
    explorar: "M12 3a9 9 0 1 0 0 18a9 9 0 0 0 0-18zM3 12h18M12 3c2.5 2.5 4 5.6 4 9s-1.5 6.5-4 9c-2.5-2.5-4-5.6-4-9s1.5-6.5 4-9z",
    comparar: "M3 4h5v16H3zM10 4h5v16h-5zM17 4h4v16h-4z",
    bordo: "M3 5h18v12H3zM8 21h8M12 17v4",
    evidencias: "M12 4a6 6 0 1 0 0 12a6 6 0 0 0 0-12zM9 15l-2 6 5-2 5 2-2-6M9.5 10l2 2 3-3.5",
    terreno: "M9 4h6l2 7H7zM7 11l-3 8M17 11l3 8M10 11l-1 8M14 11l1 8M2 19h5M17 19h5",
    aula: "M3 6h18v11H3zM8 21h8M12 17v4M7 10h6",
};
const icon = (d) => h("svg", { viewBox: "0 0 24 24", class: "i", "aria-hidden": "true" },
    h("path", { d: d }));
export const ROUTE_NAMES = {
    "/": "Escolha", "/explorar": "Explorar o polo sul", "/comparar": "Comparar locais", "/comparar/tecnico": "Comparação técnica",
    "/aula": "Modo apresentação", "/aula/atividade": "Atividade guiada", "/bordo": "Painel de bordo", "/evidencias": "Fontes e limitações", "/terreno": "Terreno 3D",
};
const view = (name) => async (outlet, ctx) => {
    let mod;
    try {
        mod = await import(`./views/${name}.js`);
    }
    catch (e) {
        mount(outlet, h("section", { class: "glass card" },
            h("h1", { class: "title-l", "data-route-title": "" }, ROUTE_NAMES[ctx.path] || name),
            h("p", { class: "t2" }, "Esta tela ainda não foi carregada: " + e.message)));
        return;
    }
    await mod.render(outlet, ctx);
};
/** Scenario handed to the Polar Lab: same site and window start (t) as the shell view. */
const labHash = (q) => { const p = new URLSearchParams(); if (q.site)
    p.set("site", q.site); if (q.t)
    p.set("t", q.t); if (q.d)
    p.set("d", q.d); const s = p.toString(); return s ? "#" + s : ""; };
const routes = [
    { path: "/", title: "Escolha", render: view("escolha") },
    { path: "/explorar", title: "Explorar o polo sul", render: view("explorar") },
    { path: "/comparar", title: "Comparar locais", render: view("comparar") },
    { path: "/comparar/tecnico", title: "Comparação técnica", render: view("tecnico") },
    { path: "/aula", title: "Modo apresentação", render: view("aula") },
    { path: "/aula/atividade", title: "Atividade guiada", render: view("atividade") },
    { path: "/evidencias", title: "Fontes e limitações", render: view("evidencias") },
    // Board and 3D lab live on their own pages; replace() keeps the back button working (no redirect loop).
    { path: "/bordo", prefix: true, title: "Painel de bordo", external: ctx => location.replace(bordoURL("onboard/cockpit.html", ctx.parts, ctx.query)) },
    { path: "/terreno", title: "Terreno 3D", external: ctx => { const q = new URLSearchParams(); if (ctx.site)
            q.set("site", ctx.site); if (ctx.query.t)
            q.set("t", ctx.query.t); if (ctx.query.d)
            q.set("d", ctx.query.d); location.replace("lab.html" + (q.size ? "#" + q : "")); } },
    { path: "*", notFound: true, title: "Página não encontrada", render: (outlet) => {
            mount(outlet, h("section", { class: "glass card" },
                h("h1", { class: "title-l", "data-route-title": "" }, "P\u00E1gina n\u00E3o encontrada"),
                h("p", { class: "t2" }, "Este endere\u00E7o n\u00E3o existe nesta vers\u00E3o."),
                h("a", { class: "btnA", href: "#/" }, "Voltar para a escolha")));
        } },
];
const dialog = document.getElementById("tools-dialog");
const moonStage = initMoonStage();
document.getElementById("open-tools")?.addEventListener("click", () => { if (!dialog.open)
    dialog.showModal(); });
document.getElementById("close-tools")?.addEventListener("click", () => dialog.close());
function paintChrome(ctx) {
    const q = scenarioQuery(ctx.query, ctx.site);
    const el = (id) => document.getElementById(id);
    const active = activeMode(ctx.path);
    el("top").querySelector(".brand")?.setAttribute("href", buildHash("/", q));
    if (dialog.open)
        dialog.close();
    moonStage.update(ctx);
    render(h(Fragment, null, MODES.map(n => h("a", { class: "navp", href: buildHash(n.path, q), "aria-current": n.path === active ? "page" : undefined },
        icon(ICONS[n.icon]),
        n.label))), el("nav"));
    render(h(Fragment, null, MODES.map(n => h("a", { href: buildHash(n.path, q), "aria-current": n.path === active ? "page" : undefined },
        icon(ICONS[n.icon]),
        n.action))), el("bottomnav"));
    render(h(Fragment, null, TOOLS.map(n => h("a", { class: "navp", href: buildHash(n.path, q), onClick: () => dialog.close() },
        icon(ICONS[n.icon]),
        n.label))), el("toolsnav"));
    // The Escolha shows its own short provenance notice above the task cards.
    render(ctx.path === "/" ? null : h(ProvStrip, { items: [{ kind: "est", text: "Luz e Terra: LOLA + SPICE, prévio, não revisado pela NASA" }, { kind: "sim", text: "Simulações marcadas com SIM" }], note: "Sem recomenda\u00E7\u00E3o de voo" }), el("pstrip"));
}
export function lastRouteLabel() {
    const last = loadLastRoute();
    if (!last)
        return null;
    const { path } = parseHash(last);
    const base = Object.keys(ROUTE_NAMES).filter(p => p !== "/" && (path === p || path.startsWith(p + "/"))).sort((a, b) => b.length - a.length)[0];
    return base ? { hash: last, label: ROUTE_NAMES[base] } : null;
}
startRouter({ routes, outlet: document.getElementById("view"), onAfter: paintChrome });
// The offline worker only serves a clear offline notice; API/science requests always stay network-owned.
if ("serviceWorker" in navigator && window.isSecureContext) {
    void navigator.serviceWorker.register("./sw.js").catch(() => { });
}
